class Solution {
public:
    int subsequenceCount(vector<int>& nums) {
        const int mod = 1e9 + 7;
        long long even_cnt = 0, odd_cnt = 0;
        for (int x : nums) {
            if (x % 2 != 0) {
                long long next_even = (even_cnt + odd_cnt) % mod;
                long long next_odd = (even_cnt + odd_cnt + 1) % mod;
                even_cnt = next_even;
                odd_cnt = next_odd;
            } else {
                long long next_even = (even_cnt * 2 + 1) % mod;
                long long next_odd = (odd_cnt * 2) % mod;
                even_cnt = next_even;
                odd_cnt = next_odd;
            }
        }
        return odd_cnt;
    }
};

class Solution {
    public int subsequenceCount(int[] nums) {
        int mod = 1_000_000_007;
        long evenCnt = 0, oddCnt = 0;
        for (int x : nums) {
            if (x % 2 != 0) {
                long nextEven = (evenCnt + oddCnt) % mod;
                long nextOdd = (evenCnt + oddCnt + 1) % mod;
                evenCnt = nextEven;
                oddCnt = nextOdd;
            } else {
                long nextEven = (evenCnt * 2 + 1) % mod;
                long nextOdd = (oddCnt * 2) % mod;
                evenCnt = nextEven;
                oddCnt = nextOdd;
            }
        }
        return (int) oddCnt;
    }
}

var subsequenceCount = function(nums) {
    const mod = 1000000007n;
    let evenCnt = 0n;
    let oddCnt = 0n;
    for (const x of nums) {
        if (x % 2 !== 0) {
            const nextEven = (evenCnt + oddCnt) % mod;
            const nextOdd = (evenCnt + oddCnt + 1n) % mod;
            evenCnt = nextEven;
            oddCnt = nextOdd;
        } else {
            const nextEven = (evenCnt * 2n + 1n) % mod;
            const nextOdd = (oddCnt * 2n) % mod;
            evenCnt = nextEven;
            oddCnt = nextOdd;
        }
    }
    return Number(oddCnt);
};
